import { readFile, writeFile, appendFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import path from 'node:path';
const root = './LOCAL_USER/AppData/Local/FVI-QA-Private-20260925';
const out = './LOCAL_USER/AppData/Local/Temp/fvi-batch4-candidate-20260928/output/godel-benchmark-driver-20261003/bindings-f52df692/dispatch/FVI-CORE455-20261004-A';
const journalFile = `${out}/FVI-CORE455-20261004-A-journal.jsonl`;
const bytes = await readFile(journalFile, 'utf8');
const events = bytes.trim().split('\n').map(JSON.parse);
const key = 'FVI-CORE455-20261004-A.01.repaired-governance.self-denial';
const intent = events.findLast(event => event.key === key && event.state === 'intent');
if (!intent || events.some(event => event.key === key && event.state === 'completed')) throw new Error('Exact unresolved self-refusal intent required');
const observed = events.findLast(event => event.key === 'rpc-response' && event.rpc === 'decide_recon_definition_promotion' && event.payload_sha256 === intent.payload_sha256);
if (!observed || path.dirname(path.resolve(observed.receipt_file)) !== path.resolve(root)) throw new Error('Bound private observed response required');
const response = JSON.parse(await readFile(observed.receipt_file, 'utf8'));
if (response.http !== 409 || response.actor !== 'maker' || response.rpc !== observed.rpc || response.payload_sha256 !== intent.payload_sha256 || response.result?.code !== 'PT409' || response.result?.message !== 'recon_governance.independent_checker_required') throw new Error('Specific actual independent-checker refusal required');
const ack = JSON.parse(await readFile(process.argv[2], 'utf8'));
const config = JSON.parse(await readFile(ack.config_file, 'utf8'));
const session = JSON.parse(await readFile(ack.sessions.checker, 'utf8')).session;
const transport = JSON.parse(await readFile(`${root}/FVI-QA-TRANSPORT-PROD-20261001.json`, 'utf8'));
const params = new URLSearchParams({ select:'id,tenant_id,requested_by,status,decided_by,decided_at', tenant_id:'eq.'+config.tenant_id, id:'eq.'+intent.request._request_id, limit:'2' });
const readback = await fetch(`${transport.apiUrl}/rest/v1/recon_definition_governance_requests?${params}`, { headers:{apikey:transport.anonKey,authorization:`Bearer ${session.access_token}`},redirect:'error',signal:AbortSignal.timeout(25000) });
const rows = await readback.json();
if (!readback.ok || !Array.isArray(rows) || rows.length !== 1 || rows[0].requested_by !== config.actors.maker.user_id || rows[0].status !== 'pending' || rows[0].decided_by !== null || rows[0].decided_at !== null) throw new Error('Self-refusal unchanged pending request unconfirmed');
const proof = { at:new Date().toISOString(),savedActualResponse:response,requestAfter:rows[0],ordinaryCheckerReadback:true,businessWrites:0,journalBeforeSha256:createHash('sha256').update(bytes).digest('hex'),noRpcReplay:true };
const file = `${root}/FVI-CORE455-SELF-DENIAL-RECONCILED-${Date.now()}.json`;
await writeFile(file,JSON.stringify(proof,null,2),{flag:'wx',mode:0o600});
await appendFile(journalFile,JSON.stringify({at:proof.at,key,state:'completed',payload_sha256:intent.payload_sha256,result:{denied:true,http:409,code:'PT409',reason:'recon_governance.independent_checker_required'},recovered_from_actual_response:file,noRpcReplay:true})+'\n');
console.log(JSON.stringify({selfRefusalVerified:true,pendingRequestUnchanged:true,replayed:false,proof:file}));
